import React, { useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, UserRole, Area } from '../types';
import { LayoutGrid, List, Search, Filter, Inbox, GitPullRequest, PlayCircle, CheckCircle2, ChevronDown } from 'lucide-react';
import { STATUS_BADGE_COLORS } from '../constants';

export const Board: React.FC = () => {
  const { requests, currentUser, updateStatus, setSelectedRequestId, globalFilterArea, setGlobalFilterArea, activeRole } = useSisreq();
  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [viewMode, setViewMode] = useState<'board' | 'list'>('board');
  const [searchTerm, setSearchTerm] = useState('');

  const filteredRequests = requests.filter(req => {
    let hasAccess = false;
    if (activeRole === UserRole.ADMIN || currentUser.role === UserRole.SUPERADMIN) hasAccess = true;
    else if (req.area === currentUser.area && req.status !== Status.RECIBIDO) hasAccess = true;
    if (!hasAccess) return false;
    const matchesSearch = searchTerm === '' || 
        req.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        req.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
        req.requester.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesArea = globalFilterArea === 'ALL' || req.area === globalFilterArea;
    return matchesSearch && matchesArea;
  });

  const getRequestsByStatus = (status: Status) => filteredRequests.filter(req => req.status === status);

  const handleDragOver = (e: React.DragEvent, status: Status) => {
    e.preventDefault();
    if (dragOverColumn !== status) setDragOverColumn(status);
  };

  const handleDragLeave = () => setDragOverColumn(null);

  const handleDrop = (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');
    const currentStatus = e.dataTransfer.getData('currentStatus') as Status;
    let isValidMove = false;
    if (currentUser.role === UserRole.SUPERADMIN) isValidMove = true;
    else {
        if (activeRole === UserRole.ADMIN && currentStatus === Status.RECIBIDO && targetStatus === Status.DERIVACION) isValidMove = true;
        if (activeRole === UserRole.HEAD || activeRole === UserRole.ANALYST) {
            const req = requests.find(r => r.id === requestId);
            if (req && req.area === currentUser.area) {
                if (activeRole === UserRole.HEAD && currentStatus === Status.DERIVACION && targetStatus === Status.EJECUCION) isValidMove = true;
                if (currentStatus === Status.EJECUCION && targetStatus === Status.FINALIZADO) isValidMove = true;
            }
        }
    }
    if (isValidMove) updateStatus(requestId, targetStatus);
  };

  const COLUMNS_CONFIG = [
    { title: 'Bandeja', status: Status.RECIBIDO, icon: <Inbox size={16} />, headerColor: 'text-indigo-800 bg-white border-indigo-200', bodyTint: 'bg-indigo-50/20' },
    { title: 'Derivación', status: Status.DERIVACION, icon: <GitPullRequest size={16} />, headerColor: 'text-orange-800 bg-white border-orange-200', bodyTint: 'bg-orange-50/10' },
    { title: 'Ejecución', status: Status.EJECUCION, icon: <PlayCircle size={16} />, headerColor: 'text-amber-900 bg-white border-amber-200', bodyTint: 'bg-amber-50/10' },
    { title: 'Finalizado', status: Status.FINALIZADO, icon: <CheckCircle2 size={16} />, headerColor: 'text-emerald-900 bg-white border-emerald-200', bodyTint: 'bg-emerald-50/10' }
  ];

  const getBoardTitle = () => {
    if (currentUser.role === UserRole.SUPERADMIN) return "Monitor Maestro";
    if (activeRole === UserRole.ADMIN) return "Administración Central";
    if (activeRole === UserRole.HEAD) return `Unidad ${currentUser.area}`;
    return `Operaciones ${currentUser.area}`;
  };

  return (
    <div className="flex flex-col h-full bg-[#F1F5F9]">
      {/* Search and Filters Bar - Optimized Space */}
      <div className="px-8 py-3.5 flex flex-col md:flex-row md:items-center justify-between gap-4 shrink-0 bg-white border-b border-slate-200/60 shadow-sm z-20">
          <div className="flex items-center gap-3">
             <h2 className="text-[12px] font-bold text-slate-600 uppercase tracking-widest leading-none">
                {getBoardTitle()}
             </h2>
             <span className="bg-indigo-100 text-indigo-700 px-2 py-0.5 rounded-md text-[9px] font-bold border border-indigo-200">
                {filteredRequests.length} TICKETS
             </span>
          </div>

          <div className="flex items-center gap-3">
             <div className="relative min-w-[240px]">
                <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500"/>
                <input 
                    type="text" 
                    value={searchTerm} 
                    onChange={(e) => setSearchTerm(e.target.value)} 
                    placeholder="Buscar ticket..." 
                    className="w-full pl-9 pr-3 py-1.5 text-[11px] font-bold bg-slate-50 border border-slate-300 rounded-lg focus:bg-white focus:ring-4 focus:ring-indigo-500/5 focus:border-indigo-500 outline-none transition-all placeholder:text-slate-400"
                />
             </div>

             {(currentUser.role === UserRole.SUPERADMIN || activeRole === UserRole.ADMIN) && (
                 <div className="relative min-w-[160px]">
                    <select 
                        value={globalFilterArea} 
                        onChange={(e) => setGlobalFilterArea(e.target.value as Area | 'ALL')} 
                        className="w-full pl-3 pr-8 py-1.5 text-[11px] font-bold bg-white border border-slate-300 rounded-lg appearance-none cursor-pointer outline-none hover:border-indigo-400 transition-all text-slate-800"
                    >
                        <option value="ALL">Todas las Áreas</option>
                        {Object.values(Area).map(a => <option key={a} value={a}>{a}</option>)}
                    </select>
                    <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none text-slate-500"><ChevronDown size={12} /></div>
                 </div>
             )}

             <div className="flex bg-slate-200 p-1 rounded-lg gap-1 border border-slate-300">
                <button onClick={() => setViewMode('board')} className={`p-1.5 rounded-md transition-all ${viewMode === 'board' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-600'}`} title="Tablero"><LayoutGrid size={14} /></button>
                <button onClick={() => setViewMode('list')} className={`p-1.5 rounded-md transition-all ${viewMode === 'list' ? 'bg-white text-indigo-700 shadow-sm' : 'text-slate-600'}`} title="Listado"><List size={14} /></button>
             </div>
          </div>
      </div>

      {/* Board Content */}
      {viewMode === 'board' ? (
        <div className="flex-1 overflow-x-auto overflow-y-hidden custom-scrollbar">
            <div className="h-full flex px-6 py-6 gap-6 min-w-[1200px]">
                {COLUMNS_CONFIG.map((col) => {
                    if ((activeRole === UserRole.HEAD || activeRole === UserRole.ANALYST) && col.status === Status.RECIBIDO && currentUser.role !== UserRole.SUPERADMIN) return null;
                    const items = getRequestsByStatus(col.status);
                    const isOver = dragOverColumn === col.status;
                    return (
                        <div 
                            key={col.status} 
                            className={`
                                flex-1 flex flex-col min-w-[280px] max-w-[340px] transition-all duration-300 rounded-2xl border 
                                ${isOver ? 'bg-indigo-50 border-indigo-400 border-dashed ring-4 ring-indigo-500/5' : `${col.bodyTint} border-transparent`}
                            `} 
                            onDragOver={(e) => handleDragOver(e, col.status)} 
                            onDragLeave={handleDragLeave} 
                            onDrop={(e) => handleDrop(e, col.status)}
                        >
                            {/* Column Header */}
                            <div className={`flex items-center justify-between px-4 py-3 mx-2 mt-2 rounded-xl border shadow-sm shrink-0 font-bold text-[11px] uppercase tracking-wider ${col.headerColor}`}>
                                <div className="flex items-center gap-2.5">{col.icon}{col.title}</div>
                                <span className="bg-slate-100 border border-slate-200 px-2 py-0.5 rounded-md text-[10px] text-slate-700">{items.length}</span>
                            </div>

                            {/* Column Content */}
                            <div className="flex-1 overflow-y-auto px-2 pb-6 custom-scrollbar flex flex-col gap-1 mt-3">
                                {items.length === 0 ? (
                                    <div className={`flex-1 min-h-[160px] border-2 border-dashed rounded-2xl flex flex-col gap-3 items-center justify-center text-slate-500 mt-2 mx-1 transition-all ${isOver ? 'border-indigo-300 bg-white/50' : 'border-slate-300/40'}`}>
                                        <Inbox size={24} className="opacity-40"/>
                                        <span className="text-[9px] font-bold uppercase tracking-widest opacity-60">{isOver ? 'SOLTAR' : 'SIN TICKETS'}</span>
                                    </div>
                                ) : (
                                    items.map(req => <RequestCard key={req.id} data={req} />)
                                )}
                            </div>
                        </div>
                    )
                })}
            </div>
        </div>
      ) : (
          /* List View Content */
          <div className="flex-1 overflow-hidden px-8 py-8">
              <div className="h-full flex flex-col bg-white rounded-2xl border border-slate-300 overflow-hidden shadow-sm">
                <div className="grid grid-cols-[80px_100px_130px_2.5fr_1fr_1fr_120px] gap-6 px-10 py-4 bg-slate-100 border-b border-slate-200 text-[10px] font-black text-slate-600 uppercase tracking-wider">
                    <div>ID</div><div>Prioridad</div><div>Estado</div><div>Asunto</div><div>Solicitante</div><div>Área</div><div className="text-right">Fecha</div>
                </div>
                <div className="overflow-y-auto custom-scrollbar flex-1 p-2">
                    {filteredRequests.map(req => (
                        <div key={req.id} onClick={() => setSelectedRequestId(req.id)} className="grid grid-cols-[80px_100px_130px_2.5fr_1fr_1fr_120px] gap-6 px-8 py-3.5 bg-white hover:bg-slate-50 rounded-xl border border-transparent hover:border-slate-200 cursor-pointer transition-all mb-1 items-center text-xs group">
                            <div className="font-mono text-[10px] text-slate-600 font-bold">#{req.id.split('-')[1].substring(0,6)}</div>
                            <div><span className={`text-[9px] font-bold px-2 py-0.5 rounded-md border ${req.priority === 'Alta' ? 'bg-red-50 text-red-700 border-red-200' : 'bg-slate-100 text-slate-700 border-slate-300'}`}>{req.priority.toUpperCase()}</span></div>
                            <div><span className={`inline-block px-2 py-0.5 rounded-md text-[9px] font-bold uppercase tracking-wider ${STATUS_BADGE_COLORS[req.status]}`}>{req.status}</span></div>
                            <div className="font-bold text-slate-800 truncate group-hover:text-indigo-700 transition-colors uppercase tracking-tight">{req.title}</div>
                            <div className="text-[10px] font-bold text-slate-600 truncate uppercase">{req.requester}</div>
                            <div className="text-[10px] font-black text-indigo-700 truncate uppercase">{req.area}</div>
                            <div className="text-right text-[10px] text-slate-600 font-mono font-bold">{new Date(req.createdAt).toLocaleDateString()}</div>
                        </div>
                    ))}
                </div>
              </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { RequestCard as RequestCardType, UserRole, Status } from '../types';
import { useSisreq } from '../context/SisreqContext';
import { User as UserIcon, GripVertical, MapPin, ChevronUp, ChevronDown, Clock, Hash, Building2 } from 'lucide-react';

interface Props {
  data: RequestCardType;
}

export const RequestCard: React.FC<Props> = ({ data }) => {
  const { currentUser, setSelectedRequestId } = useSisreq();
  const [isMinimized, setIsMinimized] = useState(data.status === Status.FINALIZADO);

  useEffect(() => {
    if (data.status === Status.FINALIZADO) {
        setIsMinimized(true);
    }
  }, [data.status]);

  const isAdmin = currentUser.role === UserRole.ADMIN;
  const isSuperAdmin = currentUser.role === UserRole.SUPERADMIN;
  const isHead = currentUser.role === UserRole.HEAD;
  const isAnalyst = currentUser.role === UserRole.ANALYST;

  const isDraggable = () => {
    if (isSuperAdmin) return true;
    if (isAdmin && data.status === Status.RECIBIDO) return true;
    if (isHead && data.area === currentUser.area) {
        if (data.status === Status.DERIVACION || data.status === Status.EJECUCION) return true;
    }
    if (isAnalyst && data.area === currentUser.area) {
        if (data.status === Status.EJECUCION) return true;
    }
    return false;
  };

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData('requestId', data.id);
    e.dataTransfer.setData('currentStatus', data.status);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleCardClick = () => {
    setSelectedRequestId(data.id);
  };

  const getAccentColor = (status: Status) => {
    switch (status) {
        case Status.RECIBIDO: return 'border-indigo-500';
        case Status.DERIVACION: return 'border-orange-500';
        case Status.EJECUCION: return 'border-amber-500';
        case Status.FINALIZADO: return 'border-emerald-500';
        default: return 'border-slate-400';
    }
  };

  const priorityStyles = {
    'Alta': 'bg-red-50 text-red-600 border-red-200',
    'Media': 'bg-amber-50 text-amber-700 border-amber-200',
    'Baja': 'bg-slate-100 text-slate-700 border-slate-300'
  };

  return (
    <div 
        draggable={isDraggable()}
        onDragStart={handleDragStart}
        onClick={handleCardClick}
        className={`
            bg-white rounded-xl mb-2.5 relative group
            transition-all duration-200 ease-out
            shadow-[0_2px_8px_-4px_rgba(0,0,0,0.1)] hover:shadow-[0_8px_16px_-8px_rgba(0,0,0,0.15)]
            border border-slate-200
            border-l-[4px]
            cursor-pointer flex flex-col
            ${getAccentColor(data.status)}
            ${isDraggable() ? 'active:scale-[0.98]' : 'hover:bg-slate-50/50'}
            ${isMinimized ? 'h-[56px] py-2 px-4' : 'h-[185px] p-4'}
        `}
    >
      {/* Header Info */}
      <div className={`flex justify-between items-center shrink-0 ${isMinimized ? '' : 'mb-2.5'}`}>
        <div className="flex items-center gap-2">
            {isDraggable() && !isMinimized && (
                <div onMouseDown={(e) => e.stopPropagation()} className="p-0.5 -ml-1 text-slate-400 group-hover:text-slate-600">
                    <GripVertical size={12} />
                </div>
            )}
            <div className="flex items-center gap-1.5">
                <span className="flex items-center gap-0.5 font-mono text-[9px] text-slate-600 font-bold uppercase tracking-tight">
                    <Hash size={9} className="opacity-50" /> {data.id.split('-')[1].substring(0, 6)}
                </span>
                {data.isReturned && !isMinimized && (
                     <span className="text-[8px] bg-red-600 text-white px-1 py-0.5 rounded font-black tracking-tight animate-pulse shadow-sm uppercase">
                        REVISIÓN
                     </span>
                )}
            </div>
        </div>

        <div className="flex items-center gap-1.5">
           {!isMinimized && (
             <span className={`text-[8px] font-bold px-1.5 py-0.5 rounded border shadow-none transition-colors uppercase tracking-tight ${priorityStyles[data.priority]}`}>
               {data.priority}
             </span>
           )}
           <button 
                onClick={(e) => { e.stopPropagation(); setIsMinimized(!isMinimized); }}
                className="p-1 text-slate-400 hover:text-slate-700 hover:bg-slate-100 rounded transition-all"
           >
               {isMinimized ? <ChevronDown size={14}/> : <ChevronUp size={14}/>}
           </button>
        </div>
      </div>

      {/* Main Content Area */}
      <div className={`flex-1 overflow-hidden ${isMinimized ? 'flex items-center gap-3 pr-8' : 'flex flex-col'}`}>
        <h3 className={`font-bold text-slate-800 leading-snug tracking-tight group-hover:text-indigo-700 transition-colors 
            ${isMinimized ? 'text-[11px] truncate flex-1' : 'text-[13px] mb-2 line-clamp-2'}`}>
            {data.title}
        </h3>

        {!isMinimized && (
            <div className="flex-1 bg-slate-50/50 p-2.5 rounded-lg border border-slate-200/50 mb-3 overflow-hidden">
                <p className="text-[11px] text-slate-600 leading-normal line-clamp-2 font-semibold italic">
                    {data.detail}
                </p>
            </div>
        )}
      </div>

      {/* Refined Footer */}
      {!isMinimized ? (
          <div className="mt-auto pt-2 border-t border-slate-200/60 flex flex-col gap-1.5 shrink-0">
             <div className="flex items-center justify-between">
                <div className="flex flex-col gap-0.5">
                    <div className="flex items-center gap-1.5 text-[9px] font-black text-indigo-700 uppercase tracking-tight">
                        <MapPin size={10} className="opacity-70" /> {data.area}
                    </div>
                    <div className="flex items-center gap-1.5 text-[9px] font-bold text-slate-600 uppercase tracking-tight max-w-[140px]">
                        <Building2 size={10} className="opacity-50" />
                        <span className="truncate">{data.requester}</span>
                    </div>
                </div>

                <div className="flex flex-col items-end gap-1">
                    {data.assignedAnalyst ? (
                        <div className="flex items-center gap-1 bg-slate-200 text-slate-800 px-1.5 py-0.5 rounded text-[8px] font-bold border border-slate-300" title="Responsable">
                            <UserIcon size={9} className="opacity-70" />
                            <span className="truncate max-w-[60px]">{data.assignedAnalyst.split(' ')[0]}</span>
                        </div>
                    ) : (
                        <div className="flex items-center gap-1 text-slate-500 font-mono text-[9px] font-bold">
                            <Clock size={10} className="opacity-50" />
                            {new Date(data.createdAt).toLocaleDateString(undefined, { day: '2-digit', month: '2-digit' })}
                        </div>
                    )}
                </div>
             </div>
          </div>
      ) : (
          /* Minimized Meta (Floating) */
          <div className="absolute right-10 top-1/2 -translate-y-1/2 flex items-center gap-2 pointer-events-none opacity-70">
              <span className="text-[9px] font-bold text-slate-600 uppercase">{data.area}</span>
              <div className={`w-1 h-1 rounded-full ${data.status === Status.FINALIZADO ? 'bg-emerald-600' : 'bg-slate-500'}`}></div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { STATUS_BADGE_COLORS } from '../constants';
import { UserRole, Status } from '../types';
import { 
    X, Calendar, User, Building, AlertCircle, Clock, Tag, ArrowRight, 
    CheckCircle, Briefcase, Pencil, Save, Send, MessageSquare,
    RotateCcw, Sparkles, CheckCircle2, Circle, Eye, Hash
} from 'lucide-react';

export const RequestDetailModal: React.FC = () => {
  const { 
    selectedRequestId, 
    setSelectedRequestId, 
    requests, 
    currentUser, 
    updateStatus, 
    returnRequest, 
    assignAnalyst,
    updateRequestDetails,
    addLog,
    users,
    activeRole
  } = useSisreq();

  const [returnReason, setReturnReason] = useState('');
  const [showReturnInput, setShowReturnInput] = useState(false);
  const [showAnalystSelect, setShowAnalystSelect] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editTitle, setEditTitle] = useState('');
  const [editDetail, setEditDetail] = useState('');
  const [newComment, setNewComment] = useState('');

  const data = requests.find(r => r.id === selectedRequestId);

  useEffect(() => {
     if (data) {
        setEditTitle(data.title);
        setEditDetail(data.detail);
        setIsEditing(false);
        setShowReturnInput(false);
        setShowAnalystSelect(false);
        setNewComment('');
     }
  }, [selectedRequestId, data]);

  if (!selectedRequestId || !data) return null;

  const handleClose = () => setSelectedRequestId(null);

  const getStatusTheme = (status: Status) => {
    switch (status) {
        case Status.RECIBIDO: 
            return { border: 'border-indigo-600', bg: 'bg-indigo-50/50', iconBg: 'bg-indigo-700', iconColor: 'text-indigo-700' };
        case Status.DERIVACION: 
            return { border: 'border-orange-600', bg: 'bg-orange-50/50', iconBg: 'bg-orange-700', iconColor: 'text-orange-700' };
        case Status.EJECUCION: 
            return { border: 'border-amber-600', bg: 'bg-amber-50/50', iconBg: 'bg-amber-700', iconColor: 'text-amber-700' };
        case Status.FINALIZADO: 
            return { border: 'border-emerald-600', bg: 'bg-emerald-50/50', iconBg: 'bg-emerald-700', iconColor: 'text-emerald-700' };
        default: 
            return { border: 'border-slate-700', bg: 'bg-slate-50/50', iconBg: 'bg-slate-800', iconColor: 'text-slate-800' };
    }
  };

  const theme = getStatusTheme(data.status);

  const handleSaveEdit = () => {
    if (editTitle.trim() && editDetail.trim()) {
        updateRequestDetails(data.id, editTitle, editDetail);
        setIsEditing(false);
    }
  };

  const handleCancelEdit = () => {
    setEditTitle(data.title);
    setEditDetail(data.detail);
    setIsEditing(false);
  };

  const handleAddComment = () => {
      if (newComment.trim()) {
          addLog(data.id, `Nota: ${newComment}`);
          setNewComment('');
      }
  }

  const handleDerive = () => {
    if (confirm('¿Derivar este requerimiento al área correspondiente?')) {
      updateStatus(data.id, Status.DERIVACION);
    }
  };

  const handleStartExecution = () => updateStatus(data.id, Status.EJECUCION);

  const handleFinalize = () => {
    if (confirm('¿Confirmar finalización del requerimiento?')) {
      updateStatus(data.id, Status.FINALIZADO);
    }
  };

  const handleReturnSubmit = () => {
    if (returnReason.trim()) {
      returnRequest(data.id, returnReason);
      setShowReturnInput(false);
      setReturnReason('');
    }
  };

  const handleAssignAnalyst = (analystName: string) => {
    assignAnalyst(data.id, analystName);
    setShowAnalystSelect(false);
  };

  const getTimelineConfig = (msg: string) => {
    const lower = msg.toLowerCase();
    if (lower.includes('devuelto')) return { bg: 'bg-red-50', text: 'text-red-700', border: 'border-red-200', icon: <RotateCcw size={12} strokeWidth={2.5} /> };
    if (lower.includes('finalizado')) return { bg: 'bg-emerald-50', text: 'text-emerald-700', border: 'border-emerald-200', icon: <CheckCircle2 size={12} strokeWidth={2.5} /> };
    if (lower.includes('nota:')) return { bg: 'bg-indigo-50', text: 'text-indigo-700', border: 'border-indigo-200', icon: <MessageSquare size={12} strokeWidth={2.5} /> };
    if (lower.includes('derivado')) return { bg: 'bg-orange-50', text: 'text-orange-700', border: 'border-orange-200', icon: <ArrowRight size={12} strokeWidth={2.5} /> };
    if (lower.includes('creado') || lower.includes('ingresado')) return { bg: 'bg-blue-50', text: 'text-blue-700', border: 'border-blue-200', icon: <Sparkles size={12} strokeWidth={2.5} /> };
    return { bg: 'bg-slate-100', text: 'text-slate-800', border: 'border-slate-300', icon: <Circle size={10} strokeWidth={2.5} /> };
  };

  const isSuperAdmin = currentUser.role === UserRole.SUPERADMIN;
  const canEdit = isSuperAdmin || 
                  (activeRole === UserRole.ADMIN && data.status === Status.RECIBIDO) || 
                  ((activeRole === UserRole.HEAD || activeRole === UserRole.ANALYST) && data.area === currentUser.area);

  const canComment = isSuperAdmin || 
                     (activeRole === UserRole.ADMIN && (data.status === Status.RECIBIDO || data.status === Status.DERIVACION)) ||
                     ((activeRole === UserRole.HEAD || activeRole === UserRole.ANALYST) && data.area === currentUser.area);

  const availableAnalysts = users.filter(u => u.role === UserRole.ANALYST && u.area === data.area);

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
