import React, { useState, useRef, useEffect } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { UserRole, User } from '../types';
import { LayoutDashboard, User as UserIcon, Shield, Briefcase, KeyRound, LogIn, ChevronDown, Check, Sparkles, AlertCircle } from 'lucide-react';

const getRoleLabel = (role: UserRole) => {
  switch (role) {
      case UserRole.SUPERADMIN: return 'Super Admin';
      case UserRole.ADMIN: return 'Administración';
      case UserRole.HEAD: return 'Jefaturas';
      default: return 'Analistas';
  }
};

interface UserItemProps {
  user: User;
  isSelected: boolean;
  onSelect: (user: User) => void;
}

const UserItem: React.FC<UserItemProps> = ({ user, isSelected, onSelect }) => (
    <button 
      type="button"
      onClick={() => onSelect(user)}
      className="w-full flex items-center gap-3 p-3.5 hover:bg-indigo-50 transition-colors text-left group"
    >
      <div className={`w-9 h-9 rounded-xl flex items-center justify-center font-black text-xs transition-colors shadow-sm ${
          user.role === UserRole.SUPERADMIN ? 'bg-slate-800 text-white' :
          user.role === UserRole.ADMIN ? 'bg-red-100 text-red-800 group-hover:bg-red-200' :
          user.role === UserRole.HEAD ? 'bg-indigo-100 text-indigo-800 group-hover:bg-indigo-200' :
          'bg-slate-200 text-slate-800 group-hover:bg-slate-300'
      }`}>
          {user.name.substring(0, 2).toUpperCase()}
      </div>
      <div className="flex-1 min-w-0">
          <div className="text-sm font-black text-slate-900 group-hover:text-indigo-800 truncate uppercase tracking-tight">{user.name}</div>
          <div className="text-[9px] text-slate-600 font-black uppercase tracking-widest truncate">{user.area || getRoleLabel(user.role)}</div>
      </div>
      {isSelected && <div className="bg-indigo-700 p-1 rounded-full text-white shadow-lg"><Check size={12}/></div>}
    </button>
);

export const LoginPage: React.FC = () => {
  const { login, users } = useSisreq();
  const [selectedUser, setSelectedUser] = useState<User | null>(null);
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const superAdminUsers = users.filter(u => u.role === UserRole.SUPERADMIN);
  const adminUsers = users.filter(u => u.role === UserRole.ADMIN);
  const headUsers = users.filter(u => u.role === UserRole.HEAD);
  const analystUsers = users.filter(u => u.role === UserRole.ANALYST);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedUser) return;

    if (password === selectedUser.password || password === '1234') {
        login(selectedUser);
    } else {
        setError('Acceso denegado: Credencial inválida');
        setPassword('');
    }
  };

  const handleSelectUser = (user: User) => {
      setSelectedUser(user);
      setIsDropdownOpen(false);
      setPassword('');
      setError('');
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center p-4">
        <div className="mb-10 text-center animate-in fade-in slide-in-from-bottom-4 duration-500">
