                <div className="bg-indigo-700 p-3 rounded-2xl shadow-xl shadow-indigo-200">
                    <LayoutDashboard className="text-white" size={28} />
                </div>
                <div className="text-left">
                    <h1 className="text-3xl font-black tracking-tighter text-slate-900 leading-none">SISREQ</h1>
