        </div>

        <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-[0_32px_64px_-12px_rgba(0,0,0,0.2)] border border-slate-300 p-10 animate-in zoom-in-95 duration-300 relative overflow-visible">
            <div className="mb-8 flex items-center gap-3">
                <div className="bg-indigo-100 p-2 rounded-xl text-indigo-800"><Sparkles size={16}/></div>
                <h2 className="text-lg font-black text-slate-900 tracking-tight">Acceso Institucional</h2>
            </div>

            <form onSubmit={handleLogin} className="space-y-6">
                <div className="space-y-2" ref={dropdownRef}>
