                        >
                            {selectedUser ? (
                                <div className="flex items-center gap-3 min-w-0">
                                    <div className={`w-8 h-8 rounded-xl flex items-center justify-center font-black text-xs flex-shrink-0 shadow-sm ${
                                        selectedUser.role === UserRole.SUPERADMIN ? 'bg-slate-800 text-white' :
                                        selectedUser.role === UserRole.ADMIN ? 'bg-red-700 text-white' :
                                        selectedUser.role === UserRole.HEAD ? 'bg-indigo-700 text-white' :
                                        'bg-slate-500 text-white'
                                    }`}>
                                        {selectedUser.name.substring(0, 2).toUpperCase()}
