                                    <div className="text-left min-w-0">
                                        <div className="text-sm font-black text-slate-900 truncate uppercase tracking-tight">{selectedUser.name}</div>
                                        <div className="text-[8px] text-slate-600 font-black uppercase tracking-widest truncate">{selectedUser.area || getRoleLabel(selectedUser.role)}</div>
                                    </div>
