                            <ChevronDown size={18} className={`text-slate-500 transition-transform flex-shrink-0 ${isDropdownOpen ? 'rotate-180 text-indigo-700' : ''}`}/>
                        </button>

                        {isDropdownOpen && (
                            <div className="absolute top-full left-0 right-0 mt-3 bg-white rounded-3xl shadow-2xl border border-slate-300 z-50 max-h-72 overflow-y-auto custom-scrollbar animate-in fade-in slide-in-from-top-2">
                                {superAdminUsers.length > 0 && (
                                    <>
