import React, { useMemo, useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { Status, Area, Priority, UserRole } from '../types';
import { 
    BarChart3, TrendingUp, CheckCircle2, Clock, 
    Activity, AlertTriangle, CalendarRange, ArrowRight,
    Briefcase, Zap, Layers, Filter, Target, Calendar
} from 'lucide-react';

export const ReportsView: React.FC = () => {
  const { requests, users, setViewMode, setGlobalFilterArea } = useSisreq();
  const [timeRange, setTimeRange] = useState<'Semanal' | 'Mensual' | 'Anual' | 'Todo'>('Mensual');

  const filteredRequests = useMemo(() => {
    if (timeRange === 'Todo') return requests;
    const now = new Date();
    return requests.filter(r => {
        const reqDate = new Date(r.createdAt);
        const diffTime = Math.abs(now.getTime() - reqDate.getTime());
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
        if (timeRange === 'Semanal') return diffDays <= 7;
        if (timeRange === 'Mensual') return diffDays <= 30;
        if (timeRange === 'Anual') return diffDays <= 365;
        return true;
    });
  }, [requests, timeRange]);

  const stats = useMemo(() => {
    const total = filteredRequests.length;
    const completed = filteredRequests.filter(r => r.status === Status.FINALIZADO).length;
    const pending = total - completed;
    const completionRate = total > 0 ? Math.round((completed / total) * 100) : 0;
    const byStatus = [Status.RECIBIDO, Status.DERIVACION, Status.EJECUCION, Status.FINALIZADO].map(status => {
        const count = filteredRequests.filter(r => r.status === status).length;
        const percentage = total > 0 ? Math.round((count / total) * 100) : 0;
        return { name: status, count, percentage };
    });
    const completedItems = filteredRequests.filter(r => r.status === Status.FINALIZADO && r.finishedAt);
    let avgDays = 0;
    if (completedItems.length > 0) {
        const totalMs = completedItems.reduce((acc, curr) => {
            const start = new Date(curr.createdAt).getTime();
            const end = new Date(curr.finishedAt!).getTime();
            return acc + (end - start);
        }, 0);
        avgDays = Number((totalMs / (1000 * 60 * 60 * 24) / completedItems.length).toFixed(1));
    }
    const byPriority = Object.values(Priority).map(p => ({
        name: p,
        count: filteredRequests.filter(r => r.priority === p).length
    }));
    return { total, completed, pending, completionRate, byStatus, avgDays, byPriority };
  }, [filteredRequests]);

  return (
    <div className="flex-1 overflow-y-auto custom-scrollbar p-8 space-y-10 bg-[#F8FAFC]">
        {/* Header Section */}
        <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
            <div className="flex flex-col gap-2">
                <div className="flex items-center gap-3">
                    <div className="p-2.5 bg-indigo-700 text-white rounded-xl shadow-lg shadow-indigo-200">
                        <BarChart3 size={24} />
                    </div>
                    <h2 className="text-3xl font-black text-slate-900 tracking-tighter uppercase">Inteligencia Operativa</h2>
                </div>
                <p className="text-slate-600 text-sm font-black ml-1 flex items-center gap-2 mt-1">
                    <Calendar size={14} className="text-indigo-600" /> Periodo Analizado: <span className="text-indigo-800 font-black bg-indigo-100 px-3 py-0.5 rounded-full">{timeRange.toUpperCase()}</span>
                </p>
            </div>

            <div className="flex bg-white/90 backdrop-blur-sm p-1.5 rounded-[1.25rem] border border-slate-300 shadow-xl shadow-slate-200/50">
                {['Semanal', 'Mensual', 'Anual', 'Todo'].map((range) => (
                    <button
                        key={range}
                        onClick={() => setTimeRange(range as any)}
                        className={`px-6 py-2.5 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${
                            timeRange === range 
                            ? 'bg-slate-900 text-white shadow-xl' 
                            : 'text-slate-600 hover:text-slate-900 hover:bg-slate-100'
                        }`}
                    >
                        {range}
                    </button>
                ))}
            </div>
        </div>

        {/* Stats Grid */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            {[
                { label: 'Total Tickets', val: stats.total, icon: <Briefcase size={22}/>, color: 'bg-indigo-700', trend: 'Global' },
                { label: 'En Proceso', val: stats.pending, icon: <Zap size={22}/>, color: 'bg-amber-600', trend: 'Activos' },
                { label: 'Eficiencia', val: `${stats.completionRate}%`, icon: <Target size={22}/>, color: 'bg-emerald-600', trend: 'Resolución' },
                { label: 'T. Promedio', val: `${stats.avgDays}d`, icon: <Clock size={22}/>, color: 'bg-blue-600', trend: 'SLA' }
            ].map((card, i) => (
                <div key={i} className="bg-white p-7 rounded-[2rem] border border-slate-300 shadow-[0_10px_30px_-15px_rgba(0,0,0,0.12)] hover:-translate-y-2 transition-all duration-300 group">
                    <div className="flex items-center justify-between mb-6">
                        <div className={`p-3.5 ${card.color} text-white rounded-2xl shadow-lg transition-transform group-hover:rotate-6`}>
                            {card.icon}
                        </div>
                        <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">{card.trend}</span>
                    </div>
                    <div>
                        <p className="text-4xl font-black text-slate-900 tracking-tighter">{card.val}</p>
                        <p className="text-[11px] font-black text-slate-600 uppercase tracking-widest mt-2">{card.label}</p>
                    </div>
                </div>
            ))}
        </div>

        {/* Charts Section */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            {/* Workflow Progress */}
            <div className="lg:col-span-2 bg-white rounded-[2.5rem] shadow-2xl shadow-slate-200/50 border border-slate-300 p-8 md:p-10">
                <div className="flex items-center justify-between mb-10">
                    <h3 className="font-black text-slate-900 uppercase tracking-tight text-lg flex items-center gap-3">
                        <Layers size={22} className="text-indigo-700"/> Distribución de Ciclo de Vida
                    </h3>
                </div>
                <div className="space-y-8">
                    {stats.byStatus.map((step) => (
                        <div key={step.name} className="group">
                            <div className="flex justify-between items-end mb-3 text-xs font-black uppercase tracking-widest">
                                <span className="text-slate-600 group-hover:text-indigo-800 transition-colors">{step.name}</span>
                                <span className="text-slate-900">{step.count} ({step.percentage}%)</span>
                            </div>
                            <div className="w-full h-4 bg-slate-200 rounded-full border border-slate-300 overflow-hidden p-0.5">
                                <div 
                                    className={`h-full rounded-full transition-all duration-1000 ease-out shadow-sm ${
                                        step.name === Status.FINALIZADO ? 'bg-emerald-600' : 
                                        step.name === Status.RECIBIDO ? 'bg-indigo-600' :
                                        step.name === Status.DERIVACION ? 'bg-orange-600' : 'bg-amber-600'
                                    }`}
                                    style={{ width: `${Math.max(step.percentage, 2)}%` }}
                                ></div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>

            {/* Priorities Chart */}
            <div className="bg-white rounded-[2.5rem] shadow-2xl shadow-slate-200/50 border border-slate-300 p-8 md:p-10">
                <h3 className="font-black text-slate-900 uppercase tracking-tight text-lg mb-10 flex items-center gap-3">
                    <AlertTriangle size={22} className="text-amber-600"/> Urgencia Operativa
                </h3>
                <div className="flex items-end justify-between gap-6 h-56 px-4">
                    {stats.byPriority.map((p) => {
                         const height = stats.total > 0 ? (p.count / stats.total) * 100 : 0;
                         return (
                            <div key={p.name} className="flex flex-col items-center gap-4 flex-1 group">
                                <div className="text-xs font-black text-slate-900 opacity-0 group-hover:opacity-100 transition-opacity bg-slate-200 px-2 py-1 rounded-lg">
                                    {p.count}
                                </div>
                                <div className="w-full relative flex items-end justify-center h-40 bg-slate-100 rounded-2xl border border-slate-200 overflow-hidden">
                                    <div 
                                        className={`w-full transition-all duration-1000 ease-out ${
                                            p.name === Priority.HIGH ? 'bg-gradient-to-t from-red-700 to-red-500' : 
                                            p.name === Priority.MEDIUM ? 'bg-gradient-to-t from-amber-700 to-amber-500' : 'bg-gradient-to-t from-slate-500 to-slate-400'
                                        }`} 
                                        style={{ height: `${Math.max(height, 8)}%` }}
                                    ></div>
                                </div>
                                <div className="text-[10px] font-black text-slate-600 uppercase tracking-widest">{p.name}</div>
                            </div>
                         );
                    })}
                </div>
            </div>
        </div>
    </div>
  );
};

