             <div>
                <div className="flex items-center gap-2 mb-1">
                    <span className="px-2.5 py-1 rounded-lg text-[10px] font-black uppercase tracking-wider shadow-sm bg-indigo-100 text-indigo-800 border border-indigo-300">
                        NUEVO TICKET
                    </span>
                    <span className="flex items-center gap-1 text-[11px] text-slate-600 font-mono font-black tracking-tighter bg-white/80 px-2 py-0.5 rounded-md border border-slate-200">
                        <Hash size={10}/>AUTOGENERADO
                    </span>
                </div>
                <h2 className="text-xl font-black text-slate-900 leading-tight tracking-tight">Registrar Requerimiento</h2>
             </div>
          </div>
          <button 
            onClick={onClose} 
            className="text-slate-500 hover:text-slate-800 p-2.5 hover:bg-white rounded-full transition-all border border-transparent hover:border-slate-300 shadow-none hover:shadow-sm"
          >
            <X size={22} />
          </button>
        </div>

        {/* Form Body */}
        <div className="flex-1 overflow-y-auto custom-scrollbar bg-white">
          <form id="new-request-form" onSubmit={handleSubmit} className="p-8 space-y-8">

            {/* Sección: Origen */}
            <div className="space-y-3">
              <label className="text-[10px] font-black text-slate-600 uppercase tracking-widest flex items-center gap-2.5">
                  <User size={14} className="text-indigo-700" /> Origen de la Solicitud
              </label>
              <input
                  type="text"
                  required
                  className="w-full bg-slate-50 border-2 border-slate-200 text-slate-900 text-sm rounded-2xl px-5 py-4 focus:outline-none focus:ring-8 focus:ring-indigo-500/5 focus:border-indigo-600 transition-all placeholder:text-slate-500 font-bold shadow-inner"
                  value={requester}
                  onChange={(e) => setRequester(e.target.value)}
                  placeholder="Unidad solicitante (ej: Gerencia Comercial)"
                  autoFocus
              />
            </div>

            {/* Sección: Título */}
            <div className="space-y-3">
                <label className="text-[10px] font-black text-slate-600 uppercase tracking-widest flex items-center gap-2.5">
                    <Tag size={14} className="text-indigo-700" /> Asunto del Requerimiento
                </label>
                <input
                    type="text"
                    required
                    className="w-full bg-slate-50 border-2 border-slate-200 text-slate-900 text-sm rounded-2xl px-5 py-4 focus:outline-none focus:ring-8 focus:ring-indigo-500/5 focus:border-indigo-600 transition-all font-bold shadow-inner"
                    value={title}
                    onChange={(e) => setTitle(e.target.value)}
                    placeholder="Resumen corto del ticket..."
                />
            </div>

            {/* Sección: Destino y Prioridad en Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-4">
                    <label className="text-[10px] font-black text-slate-600 uppercase tracking-widest flex items-center gap-2.5">
                        <Building size={14} className="text-indigo-700" /> Área de Gestión
                    </label>
                    <div className="grid grid-cols-1 gap-2.5">
                        {(Object.values(Area)).map((a) => {
                            const config = AREA_CONFIG[a];
                            const isSelected = area === a;
                            return (
                                <button
                                    key={a}
                                    type="button"
                                    onClick={() => setArea(a)}
                                    className={`
                                        relative flex items-center gap-4 p-3.5 rounded-2xl border-2 text-left transition-all duration-300 group
                                        ${isSelected 
                                            ? 'border-indigo-700 bg-indigo-50/50 shadow-md' 
                                            : 'border-slate-200 bg-slate-50/30 hover:border-slate-300 hover:bg-slate-100'}
                                    `}
                                >
                                    <div className={`
                                        p-2 rounded-xl transition-all
                                        ${isSelected ? 'bg-indigo-700 text-white shadow-lg' : 'bg-white text-slate-500 border border-slate-200'}
                                    `}>
                                        {config.icon}
                                    </div>
                                    <div className="min-w-0">
                                        <div className={`text-[13px] font-black truncate tracking-tight ${isSelected ? 'text-indigo-900' : 'text-slate-800'}`}>{a}</div>
                                        <div className="text-[9px] text-slate-600 font-bold truncate">{config.desc}</div>
                                    </div>
                                </button>
                            );
                        })}
                    </div>
                </div>

                <div className="space-y-4">
                    <label className="text-[10px] font-black text-slate-600 uppercase tracking-widest flex items-center gap-2.5">
                        <AlertCircle size={14} className="text-indigo-700" /> Nivel de Urgencia
                    </label>
                    <div className="flex flex-col bg-slate-50 p-3 rounded-[2rem] gap-2 border border-slate-200">
                        {(Object.values(Priority)).map((p) => (
                            <button
                                key={p}
                                type="button"
                                onClick={() => setPriority(p)}
                                className={`
                                    w-full py-4 text-[11px] font-black uppercase tracking-widest rounded-xl transition-all border-2
                                    ${priority === p 
                                        ? p === Priority.HIGH ? 'bg-red-700 border-red-800 text-white shadow-lg shadow-red-200' :
                                          p === Priority.MEDIUM ? 'bg-amber-600 border-amber-700 text-white shadow-lg shadow-amber-200' :
                                          'bg-emerald-700 border-emerald-800 text-white shadow-lg shadow-emerald-200'
                                        : 'bg-white border-slate-200 text-slate-600 hover:text-slate-900 hover:border-slate-400'}
                                `}
                            >
                                {p}
                            </button>
                        ))}
                    </div>
                </div>
            </div>

            {/* Detalle */}
            <div className="space-y-3">
                <label className="text-[10px] font-black text-slate-600 uppercase tracking-widest flex items-center gap-2.5">
                    <AlignLeft size={14} className="text-indigo-700" /> Memoria Descriptiva
                </label>
                <textarea
                    required
                    rows={5}
                    className="w-full bg-slate-50 border-2 border-slate-200 text-slate-800 text-[14px] rounded-[2rem] px-6 py-5 focus:outline-none focus:ring-8 focus:ring-indigo-500/5 focus:border-indigo-600 transition-all resize-none font-bold leading-relaxed shadow-inner italic"
                    value={detail}
                    onChange={(e) => setDetail(e.target.value)}
                    placeholder="Detalle los alcances técnicos de su requerimiento aquí..."
                />
            </div>
          </form>
        </div>

        {/* Footer Actions */}
        <div className="bg-white border-t border-slate-200 p-6 flex items-center justify-between gap-4 shrink-0 z-20">
            <button
                type="button"
                onClick={onClose}
                className="px-6 py-3.5 text-slate-600 font-black text-[11px] uppercase tracking-widest hover:bg-slate-100 rounded-2xl transition-all"
            >
                Cancelar
            </button>
            <button
                form="new-request-form"
                type="submit"
                className="bg-indigo-700 hover:bg-indigo-800 text-white py-4 px-10 rounded-2xl text-[11px] font-black uppercase tracking-widest shadow-2xl shadow-indigo-200 flex items-center gap-3 transition-all active:scale-95"
            >
                <Send size={18} strokeWidth={3}/> Registrar Ticket
            </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { UserRole, Area } from '../types';
import { LayoutDashboard, Plus, Briefcase, LogOut, Shield, ArrowLeftRight } from 'lucide-react';
import { NewRequestModal } from './NewRequestModal';
import { RequestDetailModal } from './RequestDetailModal';

export const Layout: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { currentUser, logout, viewMode, setViewMode, activeRole, setActiveRole, setGlobalFilterArea } = useSisreq();
  const [isModalOpen, setIsModalOpen] = useState(false);

  const getInitials = (name: string) => name.substring(0, 2).toUpperCase();
  const isHybridUser = currentUser.role === UserRole.ADMIN && !!currentUser.area;

  const handleToggleProfile = () => {
    if (activeRole === UserRole.ADMIN) {
        setActiveRole(UserRole.HEAD);
        setGlobalFilterArea(currentUser.area as Area);
    } else {
        setActiveRole(UserRole.ADMIN);
        setGlobalFilterArea('ALL');
    }
  };

  const getRoleBadge = () => {
    if (isHybridUser) {
        return (
            <button 
                onClick={handleToggleProfile}
                className={`flex items-center gap-1.5 px-2 py-0.5 rounded-lg text-[9px] font-black border transition-all ${
                    activeRole === UserRole.ADMIN 
                    ? 'bg-red-50 text-red-700 border-red-200 hover:bg-red-100' 
                    : 'bg-indigo-50 text-indigo-700 border-indigo-200 hover:bg-indigo-100'
                }`}
            >
                <ArrowLeftRight size={10} />
                {activeRole === UserRole.ADMIN ? 'MODO ADMIN' : `JEFE ${currentUser.area?.toUpperCase()}`}
            </button>
        );
    }

    switch (currentUser.role) {
        case UserRole.SUPERADMIN: return <span className="px-2 py-0.5 rounded-lg text-[9px] bg-slate-900 text-white font-black border border-black tracking-wider">SUPERADMIN</span>;
        case UserRole.ADMIN: return <span className="px-2 py-0.5 rounded-lg text-[9px] bg-slate-100 text-slate-800 font-black border border-slate-300 tracking-wider uppercase">ADMIN</span>;
        default: return <span className="px-2 py-0.5 rounded-lg text-[9px] bg-slate-100 text-slate-700 font-black border border-slate-300 tracking-wider uppercase">{currentUser.role}</span>;
    }
  };

  return (
    <div className="flex flex-col h-screen bg-[#F8FAFC] overflow-hidden font-sans">
      <header className="bg-white border-b border-slate-300 z-30 shrink-0 h-14 px-6 flex items-center justify-between">
        <div className="flex items-center gap-6">
            <div className="flex items-center gap-3 pr-6 border-r border-slate-200">
                <div className="bg-slate-200 p-1.5 rounded-lg text-slate-700">
                    <LayoutDashboard size={18} />
                </div>
                <h1 className="text-sm font-black tracking-tight text-slate-700 leading-none">SISREQ</h1>
            </div>

            <nav className="flex items-center gap-4">
                {currentUser.role === UserRole.SUPERADMIN ? (
                    <div className="flex bg-slate-200 p-1 rounded-lg gap-1 border border-slate-300">
                        <button onClick={() => setViewMode('work')} className={`px-3 py-1 rounded-md transition-all text-[11px] ${viewMode === 'work' ? 'bg-white text-indigo-800 shadow-sm font-black' : 'text-slate-600 hover:text-slate-900'}`}>
                            Tablero
                        </button>
                        <button onClick={() => setViewMode('superadmin')} className={`px-3 py-1 rounded-md transition-all text-[11px] ${viewMode === 'superadmin' ? 'bg-slate-800 text-white shadow-sm font-black' : 'text-slate-600 hover:text-slate-900'}`}>
                            Master
                        </button>
                    </div>
                ) : (
                    <div className="flex items-center gap-2 text-slate-700">
                        {activeRole === UserRole.ADMIN ? <Shield size={14}/> : <Briefcase size={14}/>}
                        <span className="text-[11px] font-black uppercase tracking-tight">
                            {activeRole === UserRole.ADMIN ? 'Consola Central' : `${activeRole} ${currentUser.area || ''}`}
                        </span>
                    </div>
                )}
            </nav>
        </div>

        <div className="flex items-center gap-4">
            {(currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.SUPERADMIN) && (
                <button 
                    onClick={() => setIsModalOpen(true)}
                    className="bg-indigo-700 hover:bg-indigo-800 text-white px-4 py-1.5 rounded-lg flex items-center gap-2 text-[11px] font-black transition-all shadow-md active:scale-95"
                >
                    <Plus size={14} /> 
                    <span className="uppercase">Nuevo Ticket</span>
                </button>
            )}

            <div className="h-6 w-px bg-slate-200 mx-1"></div>

            <div className="flex items-center gap-3">
                <div className="flex flex-col items-end">
                    <span className="text-[12px] font-black text-slate-800 leading-none mb-1">{currentUser.name}</span>
                    {getRoleBadge()}
                </div>
                <div className="w-8 h-8 rounded-lg bg-slate-100 border border-slate-300 flex items-center justify-center font-black text-[10px] text-slate-700 shrink-0">
                    {getInitials(currentUser.name)}
                </div>
                <button onClick={logout} className="p-1.5 text-slate-400 hover:text-red-700 transition-colors" title="Salir">
                    <LogOut size={18} />
                </button>
            </div>
        </div>
      </header>

      <main className="flex-1 flex flex-col min-h-0 relative">
        {children}
        <div className="absolute inset-0 opacity-[0.2] pointer-events-none" 
             style={{backgroundImage: 'radial-gradient(#94a3b8 1px, transparent 1px)', backgroundSize: '40px 40px'}}>
        </div>
      </main>

      <NewRequestModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} />
      <RequestDetailModal />
    </div>
  );
};
